-- =========================================
-- Artists: add YouTube Topic channel ID
-- =========================================
-- Promotes the YouTube spike into a proper two-channel model.
--
-- youtube_channel_id:        Official Artist Channel (Watch) — the artist-owned channel
--                             where they upload music videos, interviews, live sets, etc.
--                             Identified by a custom @handle; title is the artist name.
--
-- youtube_topic_channel_id:  "– Topic" channel (releases) — auto-generated by YouTube
--                             Music for each artist; title ends " - Topic". Used for
--                             canonical release ingestion (official audio uploads).
--
-- Both are nullable — populated incrementally via the admin resolution UI.
-- Existing RLS ("Admins can manage artists") already covers these columns.

ALTER TABLE artists
  ADD COLUMN IF NOT EXISTS youtube_topic_channel_id TEXT;

COMMENT ON COLUMN artists.youtube_channel_id IS
  'Official Artist Channel (Watch) — artist-owned channel; title = artist name';

COMMENT ON COLUMN artists.youtube_topic_channel_id IS
  '"– Topic" channel (releases) — auto-generated by YouTube Music; title ends " - Topic"';

-- Reload PostgREST schema cache so the new column is immediately available.
NOTIFY pgrst, 'reload schema';
